    10	// Column positions in /proc/net/route.
    11	const (
    12		colIface   = 0
    13		colDest    = 1
    14		colGateway = 2
    15		colMetric  = 6
    16		routeCols  = 7
    17	)
    18	
    19	// defaultGateway returns the interface and gateway of the default route with
    20	// the lowest metric in a /proc/net/route dump (the first one on equal
    21	// metrics). ok is false when there is no such route, or when that route has no
    22	// gateway (0.0.0.0): a higher-metric route is never used instead. Lines with
    23	// too few columns, an undecodable gateway or a non-numeric metric are skipped.
    24	func defaultGateway(procNetRoute []byte) (iface string, gw netip.Addr, ok bool) {
    25		var best uint64
    26		for _, line := range strings.Split(string(procNetRoute), "\n") {
    27			f := strings.Fields(line)
    28			if len(f) < routeCols || f[colDest] != "00000000" {
    29				continue
    30			}
    31			addr, valid := parseLEAddr(f[colGateway])
    32			if !valid {
    33				continue
    34			}
    35			metric, err := strconv.ParseUint(f[colMetric], 10, 32)
    36			if err != nil {
    37				continue
    38			}
    39			if !ok || metric < best {
    40				iface, gw, best, ok = f[colIface], addr, metric, true
    41			}
    42		}
    43		if !ok || gw.IsUnspecified() {
    44			return "", netip.Addr{}, false
    45		}
    46		return iface, gw, true
    47	}
    48	
    49	// parseLEAddr decodes the little-endian hex IPv4 address used by /proc/net/route.
    50	func parseLEAddr(s string) (netip.Addr, bool) {
    51		b, err := hex.DecodeString(s)
    52		if err != nil || len(b) != 4 {
    53			return netip.Addr{}, false
    54		}
    55		return netip.AddrFrom4([4]byte{b[3], b[2], b[1], b[0]}), true
    56	}
